function num(s){return s.replace(/\$(\d[\d.,]*)(K|M)?/g,function(_,a,u){return a+(u==='K'?' ألف':u==='M'?' مليون':'')+' دولار'}).replace(/(\d[\d.,]*)M\b/g,'$1 مليون').replace(/(\d[\d.,]*)K\b/g,'$1 ألف')}
function seg(s){
  var m;
  if(D.hasOwnProperty(s))return D[s];
  if(DOCW.hasOwnProperty(s))return DOCW[s];
  if(/^[+\u2212-]?\$?\d[\d.,]*[MK]?\+?%?$/.test(s)&&/[MK$%+]/.test(s))return s;
  if((m=/^(\d+) (Documents?|documents?)$/.exec(s)))return pl(m[1],'document');
  if((m=/^(\d+) pages$/.exec(s)))return pl(m[1],'page');
  if((m=/^(\d+) screenshots?$/.exec(s)))return pl(m[1],'screenshot');
  if((m=/^(\d+) posts$/.exec(s)))return pl(m[1],'post');
  if((m=/^(\d+) days?$/.exec(s)))return pl(m[1],'day');
  if((m=/^(\d+)d$/.exec(s)))return pl(m[1],'day');
  if((m=/^(\d+) documents? in (.+)$/.exec(s)))return pl(m[1],'document')+' في '+tr(m[2]);
  if((m=/^(\d+) documents? · (\d+) clients?$/.exec(s)))return pl(m[1],'document')+' · '+pl(m[2],'client');
  if((m=/^(.+), (\d+) documents?$/.exec(s))&&!D.hasOwnProperty(s))return tr(m[1])+'، '+pl(m[2],'document');
  if((m=/^(.+), (\d+) documents? for (\d+) clients?$/.exec(s)))return tr(m[1])+'، '+pl(m[2],'document')+' لـ'+pl(m[3],'client');
  if((m=/^Screenshot (\d+): (.+)$/.exec(s)))return 'لقطة الشاشة '+m[1]+': '+tr(m[2]);
  if((m=/^Screenshot (\d+)$/.exec(s)))return 'لقطة الشاشة '+m[1];
  if((m=/^Image (\d+)$/.exec(s)))return 'الصورة '+m[1];
  if((m=/^Testimonial (\d) of (\d)$/.exec(s)))return 'الشهادة '+m[1]+' من '+m[2];
  if((m=/^Team feedback \((\d) of (\d)\)$/.exec(s)))return 'رأي الفريق ('+m[1]+' من '+m[2]+')';
  if((m=/^Original Arabic feedback screenshot (\d) of (\d)$/.exec(s)))return 'لقطة الرأي الأصلية بالعربية '+m[1]+' من '+m[2];
  if((m=/^Video (\d) · (\d+:\d+)$/.exec(s)))return 'الفيديو '+m[1]+' · '+m[2];
  if((m=/^Month (\d+)$/.exec(s)))return 'الشهر '+m[1];
  if((m=/^Month (\d+) (Plan|Content Plan)$/.exec(s)))return (m[2]==='Plan'?'خطة الشهر ':'خطة محتوى الشهر ')+m[1];
  if((m=/^Social Media Plan (\d)$/.exec(s)))return 'خطة سوشيال ميديا '+m[1];
  if((m=/^(.+) logo$/.exec(s)))return 'شعار '+tr(m[1]);
  if((m=/^Open (.+)$/.exec(s)))return 'فتح '+tr(m[1]);
  if((m=/^Cover of (.+)$/.exec(s)))return 'غلاف '+tr(m[1]);
  if((m=/^(Facebook|Instagram|YouTube|TikTok|Threads|Snapchat|General evidence) analytics: (.+)$/.exec(s)))return 'تحليلات '+tr(m[1])+': '+tr(m[2]);
  if((m=/^(Facebook|Instagram|YouTube|TikTok|Threads|Snapchat) (views), (\d+) days$/.exec(s)))return 'مشاهدات '+tr(m[1])+'، '+pl(m[3],'day');
  if((m=/^(Facebook|YouTube) views, (\d+) days?$/.exec(s)))return 'مشاهدات '+tr(m[1])+'، '+pl(m[2],'day');
  if((m=/^(.+), (last )?(\d+) days$/.exec(s))&&(D.hasOwnProperty(m[1])))return D[m[1]]+'، '+(m[2]?'آخر ':'')+pl(m[3],'day');
  if((m=/^(.+), (\d+) days$/.exec(s)))return tr(m[1])+'، '+pl(m[2],'day');
  if((m=/^(.+), 365 days$/.exec(s)))return tr(m[1])+'، 365 يومًا';
  if((m=/^(Views|Post views|Accounts reached|Followers|Key metrics|Views overview|Profile insights|Insights summary), (\d+) days$/.exec(s)))return tr(m[1])+"، "+pl(m[2],"day");
  if((m=/^(\d+) days · (.+)$/.exec(s)))return pl(m[1],'day')+' · '+tr(m[2]);
  if((m=/^(\d+)d · (.+)$/.exec(s)))return pl(m[1],'day')+' · '+tr(m[2]);
  if((m=/^(\d+)d · to (.+)$/.exec(s)))return pl(m[1],'day')+' · حتى '+tr(m[2]);
  if((m=/^Last (\d+) days$/.exec(s)))return 'آخر '+pl(m[1],'day');
  if((m=/^vs previous (\d+) days · (.+)$/.exec(s)))return 'مقابل الـ'+pl(m[1],'day')+' السابقة · '+tr(m[2]);
  if((m=/^vs previous period · (.+)$/.exec(s)))return 'مقابل الفترة السابقة · '+tr(m[1]);
  if((m=/^Change vs previous period · (\d+) days$/.exec(s)))return 'التغير مقابل الفترة السابقة · '+pl(m[1],'day');
  if((m=/^(Chart axis) (.+)$/.exec(s)))return 'محور الرسم · '+tr(m[2]);
  if((m=/^Previous (\d+) days$/.exec(s)))return 'الـ'+pl(m[1],'day')+' السابقة';
  return null;
}

