function phr(t){var o=t,x=num(t);PH.forEach(function(p){x=x.replace(p[0],p[1])});return x===num(o)?null:x}
function rng(s){return s.replace(/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b/g,function(x){return MON[x]})}
function lrm(x){return x.replace(/(^|[\s(،])([+\u2212-])(\d)/g,'$1\u200E$2$3')}
function tr(s){
  var t=s.trim();if(!t)return s;
  var r=seg(t);
  if(r===null){
    // separators
    var parts,sp;
    var seps=[' · ',' — ',' – ',': ',', '];
    for(var i=0;i<seps.length;i++){
      if(t.indexOf(seps[i])>0){
        parts=t.split(seps[i]);var out=[],hit=0;
        for(var j=0;j<parts.length;j++){var q=tr(parts[j]);if(q!==parts[j])hit++;out.push(q)}
        if(hit){r=out.join(seps[i]===', '?'، ':seps[i]===': '?': ':seps[i]);break}
      }
    }
  }
  if(r===null){
    // date range "15 Nov – 12 Feb 2025"
    if(/^[\d\s]*(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b[\w\s–,.-]*$/.test(t))r=rng(t);
  }
  if(r===null){var z=phr(t);if(z!==null){z=lrm(z);return s.replace(t,function(){return z})}}
  if(r===null)return s;
  r=lrm(num(r));
  return s.replace(t,function(){return r});
}

